sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.how-section {
  width: 100%;
  padding: 90px 8%;
  background: #181818;
  font-family: Arial, sans-serif;
}

.how-heading {
  text-align: center;
  margin-bottom: 60px;
}

.how-tag {
  color: #53BA00;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 1.5px;
}

.how-heading h2 {
  margin: 12px 0;
  color: #FFFFFF;
  font-size: 36px;
  font-weight: 700;
}

.how-heading p {
  max-width: 620px;
  margin: auto;
  color: #B0B0B0;
  font-size: 16px;
  line-height: 1.6;
}

.steps-container {
  max-width: 1200px;
  margin: auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
}

.step {
  flex: 1;
  text-align: center;
  position: relative;
  min-width: 140px;
}

.step-number {
  width: 28px;
  height: 28px;
  margin: 0 auto 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;
  background: #53BA00;
  color: white;

  font-size: 13px;
  font-weight: bold;
}

.step-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 16px;
  background: #1F1F1F;
  border: 1px solid rgba(255,255,255,0.08);

  color: #53BA00;
  font-size: 26px;
}

.step h3 {
  color: #FFFFFF;
  font-size: 17px;
  margin: 0 0 10px;
}

.step p {
  color: #B0B0B0;
  font-size: 13px;
  line-height: 1.6;
  padding: 0 8px;
}

.step-line {
  width: 35px;
  height: 2px;
  margin-top: 58px;
  background: #bfdbfe;
}

@media (max-width: 768px) {

  .steps-container {
    flex-direction: column;
    align-items: center;
    gap: 25px;
  }

  .step {
    max-width: 350px;
  }

  .step-line {
    display: none;
  }

  .how-heading h2 {
    font-size: 30px;
  }
}
